import Fastify from 'fastify';
import sharp from 'sharp';
import { createProductShareCodec } from '../../dist/shared/utils/product-share-token.js';
import { registerPublicProductsRoutes } from '../../dist/interfaces/api/routes/v1/public-products.route.js';
import { registerErrorHandler } from '../../dist/interfaces/api/http/error-handler.js';
const app=Fastify(),port=3396;
const scope={tenantId:'tenant-fixture',workspaceId:'ws-fixture'};
const description='INFORMAÇÕES TÉCNICAS\n'+('Lâmpada de vidro âmbar, potência 4 W.\n'.repeat(40))+'FINAL DA DESCRIÇÃO COMPLETA';
const image=await sharp({create:{width:400,height:600,channels:3,background:{r:232,g:183,b:75}}}).jpeg().toBuffer();
const key='assets/tenant-fixture/ws-fixture/products/lampada.jpg';
const product={...scope,id:'lampada-fixture',name:'Lâmpada vintage',description,priceCents:9500,currency:'BRL',active:true,imageUrls:[`http://127.0.0.1:${port}/uploads/${key}`],costCents:1000};
const shareLinks=createProductShareCodec('public-product-browser-fixture-secret');
const token=shareLinks.create({...scope,productId:product.id});
registerErrorHandler(app);
await app.register(async sub=>registerPublicProductsRoutes(sub,{shareLinks,productRepository:{getById:async id=>id===product.id?product:undefined},salesCatalogRepository:{listVariants:async()=>[]},workspaceRepository:{getById:async()=>({...scope,id:scope.workspaceId,name:'Loja de iluminação',status:'active'})},objectStorage:{resolvePublicUrl:key=>`http://127.0.0.1:${port}/uploads/${key}`}}),{prefix:'/v1'});
app.get('/fixture/scope',async()=>({token,description}));
app.get(`/uploads/${key}`,async(_,reply)=>reply.type('image/jpeg').send(image));
app.get('/health',async()=>({ok:true}));
await app.listen({port,host:'127.0.0.1'});
for(const signal of ['SIGTERM','SIGINT'])process.on(signal,async()=>{await app.close();process.exit(0);});
